};

// --- Config ---
let mapSize = 3000; // Expanded Map
let viewportW = 300; let viewportH = 300;

let state = {
    mode: 'menu', job: null, money: 0,
    x: 0, y: 0, keys: {}, missionStage: 0,
    dialogQueue: [], followers: [],
    lastMoveSound: 0,
    // Mode States
    courier: { dest: null, houses: [], storyIndex: 0 },
    cafe: { tasks: [], timer: null },
    guide: { groupSize: 0, currentSpot: null, busOpen: false }
};

