    { txt: "有位大妈买了一整箱防晒霜，送到富人区。", targetIdx: 5, reward: 120, items: "🧴" },
    { txt: "VIP客户！送个纯金大象摆件，慢点骑！", targetIdx: 2, reward: 300, items: "🐘" },
