];

// DOM Refs
const els = {
    vp: document.getElementById('game-viewport'),
    world: document.getElementById('world-map'),
    player: document.getElementById('vith-player'),
    menu: document.getElementById('menu-screen'),
    hud: document.getElementById('game-hud'),
    money: document.getElementById('money-disp'),
