    els.world.innerHTML = ''; els.world.appendChild(els.player);
    if(state.cafe.timer) clearInterval(state.cafe.timer);
    state.followers = [];

    if(job === 'courier') setupCourier();
    else if(job === 'cafe') setupCafe();
    else if(job === 'guide') setupGuide();

    gameLoop();
}

function stopGame() {
    state.mode = 'menu';
    els.hud.style.display = 'none';
    els.menu.style.display = 'flex';
    els.arrow.style.display = 'none';
    els.choice.el.style.display = 'none';
    els.diag.el.style.display = 'none';
    if(state.cafe.timer) clearInterval(state.cafe.timer);
