// --- Game Loop ---
function gameLoop() {
    if(state.mode === 'menu') return;
    requestAnimationFrame(gameLoop);
    if(state.mode === 'dialog' || state.mode === 'choice') return;

    // Move
    let speed = (state.job==='courier' && els.player.classList.contains('riding')) ? 10 : 6; // Slightly faster for big map
    let dx=0, dy=0;
    if(state.keys['ArrowUp']||state.keys['up']) dy-=speed;
    if(state.keys['ArrowDown']||state.keys['down']) dy+=speed;
    if(state.keys['ArrowLeft']||state.keys['left']) dx-=speed;
    if(state.keys['ArrowRight']||state.keys['right']) dx+=speed;

    if(dx!==0||dy!==0) {
        state.x = Math.max(50, Math.min(mapSize-50, state.x+dx));
        state.y = Math.max(50, Math.min(mapSize-50, state.y+dy));

        const now = Date.now();
        if (now - state.lastMoveSound > 300) {
            playSnd(snd.move); state.lastMoveSound = now;
        }

        if(state.followers.length > 0) {
            let targetX = state.x; let targetY = state.y;
            state.followers.forEach((f, i) => {
                const fdx = targetX - f.x; const fdy = targetY - f.y;
                const dist = Math.sqrt(fdx*fdx + fdy*fdy);
                if(dist > 35) {
                    const angle = Math.atan2(fdy, fdx);
                    f.x += Math.cos(angle) * (speed - 1);
                    f.y += Math.sin(angle) * (speed - 1);
                }
                f.el.style.left = f.x + 'px'; f.el.style.top = f.y + 'px';
                targetX = f.x; targetY = f.y;
            });
        }
    }

    // Camera
    const vpW = els.vp.clientWidth; const vpH = els.vp.clientHeight;
    let cx = vpW/2 - state.x; let cy = vpH/2 - state.y;
    cx = Math.min(0, Math.max(cx, -(mapSize-vpW))); cy = Math.min(0, Math.max(cy, -(mapSize-vpH)));
    els.world.style.transform = `translate(${cx}px, ${cy}px)`;
    els.player.style.left = state.x + 'px'; els.player.style.top = state.y + 'px';

    if(state.job === 'guide') updateGuideNav();
    if(state.job === 'courier') updateCourierNav();
}

